import { useState } from 'react';
import { JxBadge, JxDivider, JxSelect, JxSlider, JxSwitch, JxToggle } from '@jinx-ui/react';

export type AppearanceTheme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  value?: AppearanceSettings;
  defaultValue?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const THEME_LABELS: Record<AppearanceTheme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'Без засечек' },
  { value: 'display', label: 'Fraunces', meta: 'С засечками' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'Моноширинный' },
];

const FONT_TOKENS: Record<string, string> = {
  sans: 'var(--jx-font-sans)',
  display: 'var(--jx-font-display)',
  mono: 'var(--jx-font-mono)',
};

const FALLBACK: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'sans',
};

export default function AppearanceSettingsScreen({
  value,
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [inner, setInner] = useState<AppearanceSettings>(defaultValue ?? FALLBACK);
  const settings = value ?? inner;

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    if (value === undefined) setInner(next);
    onChange?.(next);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '520px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {THEME_LABELS[settings.theme]}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>Тема оформления</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(theme) => update({ theme: theme as AppearanceTheme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <JxSelect
          label="Шрифт интерфейса"
          placeholder="Выберите шрифт"
          options={FONT_OPTIONS}
          value={settings.fontFamily}
          onValueChange={(fontFamily) => update({ fontFamily })}
        />
        <p
          style={{
            margin: 0,
            fontFamily: FONT_TOKENS[settings.fontFamily] ?? 'var(--jx-font-sans)',
            fontSize: '13px',
            color: 'var(--jx-text-2)',
          }}
        >
          Так будет выглядеть текст интерфейса.
        </p>
      </div>
    </section>
  );
}

